class Solution:
    def goodIndices(self, nums, k):
        n=len(nums)
        dec=[1]*n; inc=[1]*n
        for i in range(1,n):
            if nums[i-1]>=nums[i]: dec[i]=dec[i-1]+1
        for i in range(n-2,-1,-1):
            if nums[i]<=nums[i+1]: inc[i]=inc[i+1]+1
        return [i for i in range(k,n-k) if dec[i-1]>=k and inc[i+1]>=k]

c.cpp:
class Solution {
public:
    vector<int> goodIndices(vector<int>& nums, int k){
        int n=nums.size();
        vector<int> dec(n,1),inc(n,1),res;
        for(int i=1;i<n;i++) if(nums[i-1]>=nums[i]) dec[i]=dec[i-1]+1;
        for(int i=n-2;i>=0;i--) if(nums[i]<=nums[i+1]) inc[i]=inc[i+1]+1;
        for(int i=k;i+k<n;i++) if(dec[i-1]>=k&&inc[i+1]>=k) res.push_back(i);
        return res;
    }
};

